                {
                    Action = request.Action,
                    Accepted = accepted ? (byte)1 : (byte)0,
                    TransitionToken = request.TransitionToken,
                    SessionToken = request.SessionToken,
                    AttemptOrdinal = request.AttemptOrdinal,
                    ReasonCode = reason
                });
